126→pub(crate) fn spice_cloud_base_url(api_url_override: Option<&str>) -> String {
127→    api_url_override
128→        .map(ToString::to_string)
129→        .or_else(|| std::env::var("SPICE_CLOUD_API_URL").ok())
130→        .unwrap_or_else(|| "https://api.spice.ai".to_string())
131→        .trim_end_matches('/')
132→        .to_string()
133→}
