135→pub(crate) fn spice_cloud_token() -> anyhow::Result<String> {
136→    std::env::var("SPICEAI_API_KEY")
137→        .or_else(|_| std::env::var("SPICE_API_KEY"))
138→        .or_else(|_| std::env::var("SPICE_SPICEAI_API_KEY"))
139→        .or_else(|_| std::env::var("SPICE_SPICEAI_TOKEN"))
140→        .map_err(|_| {
141→            anyhow::anyhow!(
142→                "No Spice Cloud token found. Set one of SPICEAI_API_KEY, SPICE_API_KEY, SPICE_SPICEAI_API_KEY, or SPICE_SPICEAI_TOKEN"
143→            )
144→        })
145→}
146→
147→pub(crate) async fn ensure_spice_cloud_app(
148→    client: &Client,
149→    base_url: &str,
150→    token: &str,
151→    app_name: &str,
152→) -> anyhow::Result<(i64, Option<String>)> {
153→    let apps_url = format!("{base_url}/v1/apps");
154→    let response = client.get(&apps_url).bearer_auth(token).send().await?;
155→
156→    if response.status() == StatusCode::UNAUTHORIZED {
157→        return Err(anyhow::anyhow!(
158→            "Spice Cloud authentication failed (401). Verify your token scopes for apps:read/apps:write"
159→        ));
160→    }
161→
162→    let apps: CloudAppsResponse = response.error_for_status()?.json().await?;
163→    if let Some(app) = apps.apps.into_iter().find(|a| a.name == app_name) {
164→        return Ok((app.id, app.api_key));
165→    }
166→
167→    let cname = resolve_default_cname(client, base_url, token).await?;
168→
169→    let create_response = client
170→        .post(&apps_url)
171→        .bearer_auth(token)
172→        .json(&CloudCreateAppRequest {
173→            name: app_name.to_string(),
174→            cname,
175→            visibility: "private".to_string(),
176→            tags: BTreeMap::from([("kind".to_string(), "cluster".to_string())]),
177→        })
178→        .send()
179→        .await?;
180→
181→    if create_response.status() == StatusCode::CONFLICT {
182→        let retry = client.get(&apps_url).bearer_auth(token).send().await?;
183→        let apps: CloudAppsResponse = retry.error_for_status()?.json().await?;
184→        if let Some(app) = apps.apps.into_iter().find(|a| a.name == app_name) {
185→            return Ok((app.id, app.api_key));
186→        }
187→    }
188→
189→    let status = create_response.status();
190→    if status.is_client_error() || status.is_server_error() {
191→        let body = create_response
192→            .text()
193→            .await
194→            .unwrap_or_else(|_| "<failed to read body>".to_string());
195→        return Err(anyhow::anyhow!(
196→            "Failed to create Spice Cloud app '{app_name}' ({status}): {body}"
197→        ));
198→    }
199→
200→    let app: CloudApp = create_response.json().await?;
201→    Ok((app.id, app.api_key))
202→}
203→
204→pub(crate) async fn resolve_default_cname(
205→    client: &Client,
206→    base_url: &str,
207→    token: &str,
208→) -> anyhow::Result<String> {
209→    let regions_url = format!("{base_url}/v1/regions");
210→    let response = client.get(&regions_url).bearer_auth(token).send().await?;
211→    let regions: CloudRegionsResponse = response.error_for_status()?.json().await?;
212→
213→    // Find the region matching the `default` field, then return its cname
214→    if let Some(default_region) = &regions.default
215→        && !default_region.is_empty()
216→    {
217→        if let Some(region) = regions.regions.iter().find(|r| r.region == *default_region)
218→            && let Some(cname) = &region.cname
219→        {
220→            return Ok(cname.clone());
221→        }
222→        // Fall back to the default value itself if no matching region found
223→        return Ok(default_region.clone());
224→    }
225→
226→    if let Some(region) = regions
227→        .regions
228→        .iter()
229→        .find(|region| region.is_default && !region.disabled)
230→    {
231→        return Ok(region
232→            .cname
233→            .clone()
234→            .unwrap_or_else(|| region.region.clone()));
235→    }
236→
237→    if let Some(region) = regions.regions.iter().find(|region| !region.disabled) {
238→        return Ok(region
239→            .cname
240→            .clone()
241→            .unwrap_or_else(|| region.region.clone()));
242→    }
243→
244→    Err(anyhow::anyhow!(
245→        "Unable to determine a default Spice Cloud region (cname) for app creation"
246→    ))
247→}
