313→/// Wait for a Spice Cloud deployment to become ready by polling the SQL endpoint.
314→///
315→/// Sends `SELECT 1` to `https://{cname}.spiceai.io/v1/sql` until it returns a successful response.
316→pub(crate) async fn wait_for_deployment_ready(
317→    client: &Client,
318→    cname: &str,
319→    api_key: &str,
320→    timeout: Duration,
321→) -> anyhow::Result<()> {
322→    let sql_url = format!("https://{cname}.spiceai.io/v1/sql");
323→    eprintln!("Waiting for deployment to become ready at {sql_url}...");
324→
325→    let started = tokio::time::Instant::now();
326→    loop {
327→        if started.elapsed() > timeout {
328→            return Err(anyhow::anyhow!(
329→                "Timed out after {}s waiting for deployment to become ready at {sql_url}",
330→                timeout.as_secs(),
331→            ));
332→        }
333→
334→        let elapsed = started.elapsed().as_secs();
335→
336→        match client
337→            .post(&sql_url)
338→            .header("X-API-Key", api_key)
339→            .body("SELECT 1")
340→            .send()
341→            .await
342→        {
343→            Ok(response) if response.status().is_success() => {
344→                eprintln!("  Deployment ready ({elapsed}s elapsed)");
345→                return Ok(());
346→            }
347→            Ok(response) => {
348→                eprintln!("  Not ready: {} ({elapsed}s elapsed)", response.status());
349→            }
350→            Err(e) => {
351→                eprintln!("  Not ready: {e} ({elapsed}s elapsed)");
352→            }
353→        }
354→
355→        tokio::time::sleep(Duration::from_secs(5)).await;
356→    }
357→}
