360→impl SpicedStarter for SpiceCloudSpicedStarter {
361→    async fn start(
362→        &self,
363→        args: &CommonArgs,
364→        _start_request: StartRequest,
365→    ) -> anyhow::Result<(SpicedInstance, Option<String>)> {
366→        let base_url = spice_cloud_base_url(args.spiced_start_api_url.as_deref());
367→        let token = spice_cloud_token()?;
368→        let spicepod = Spicepod::load_exact(args.spicepod_path.clone()).await?;
369→        let app_name = sanitize_app_name(&spicepod.name);
370→        let spicepod_yaml = std::fs::read_to_string(&args.spicepod_path).map_err(|source| {
371→            anyhow::anyhow!(
372→                "Failed to read spicepod file at {}: {source}",
373→                args.spicepod_path.display()
374→            )
375→        })?;
376→
377→        let client = Client::builder()
378→            .timeout(Duration::from_secs(600))
379→            .build()?;
380→
381→        let cname = resolve_default_cname(&client, &base_url, &token).await?;
382→        let flight_url = flight_url_from_cname(&cname);
383→
384→        println!("Spice Cloud API: {base_url}");
385→        println!("Region cname: {cname}");
386→        println!("Flight endpoint: {flight_url}");
387→        println!("App name: {app_name}");
388→
389→        let (app_id, app_api_key) =
390→            ensure_spice_cloud_app(&client, &base_url, &token, &app_name).await?;
391→
392→        println!("App ID: {app_id}");
393→        println!(
394→            "App API key: {}",
395→            if app_api_key.is_some() {
396→                "<present>"
397→            } else {
398→                "<not returned>"
399→            }
400→        );
401→
402→        println!("Uploading spicepod to app...");
403→        apply_spicepod_to_app(&client, &base_url, &token, app_id, &spicepod_yaml).await?;
404→        println!("Spicepod uploaded");
405→
406→        println!("Setting secrets from spicepod...");
407→        secrets::set_spicepod_secrets(&client, &base_url, &token, app_id, &spicepod_yaml).await?;
408→        println!("Spicepod secrets set");
409→
410→        println!("Setting RUNNER secret...");
411→        secrets::set_secret(&client, &base_url, &token, app_id, "RUNNER", "spidapter").await?;
412→        println!("RUNNER secret set");
413→
414→        println!("Creating deployment...");
415→        create_deployment(&client, &base_url, &token, app_id).await?;
416→
417→        let api_key_for_poll = app_api_key.clone().ok_or_else(|| {
418→            anyhow::anyhow!("App API key is required to poll deployment readiness")
419→        })?;
420→
421→        wait_for_deployment_ready(
422→            &client,
423→            &cname,
424→            &api_key_for_poll,
425→            Duration::from_secs(args.ready_wait),
426→        )
427→        .await?;
428→
429→        let http_base_url = format!("https://{cname}.spiceai.io");
430→
431→        println!(
432→            "Spice Cloud deployment ready for app '{app_name}'. Connecting to Flight endpoint: {flight_url}",
433→        );
434→
435→        Ok((
436→            SpicedInstance::external_with_http(&flight_url, &http_base_url),
437→            app_api_key,
438→        ))
439→    }
440→}
