442→/// Derive the Flight endpoint URL from a Spice Cloud cname.
443→///
444→/// Replaces the `-data` suffix with `-flight` and constructs `https://{flight_cname}.spiceai.io`.
445→/// For example, `us-east-1-dev-aws-data` becomes `https://us-east-1-dev-aws-flight.spiceai.io`.
446→pub(crate) fn flight_url_from_cname(cname: &str) -> String {
447→    let flight_cname = if let Some(prefix) = cname.strip_suffix("-data") {
448→        format!("{prefix}-flight")
449→    } else {
450→        cname.to_string()
451→    };
452→    format!("https://{flight_cname}.spiceai.io")
453→}
454→
455→/// Sanitize a spicepod name for use as a Spice Cloud app name.
456→///
457→/// App names can only contain letters, numbers, and hyphens.
458→/// Truncated to 42 characters to leave room for Kubernetes name prefixes
459→/// and suffixes (e.g. `spicepod-{name}-scheduler-0` must be ≤63 chars).
460→pub(crate) fn sanitize_app_name(name: &str) -> String {
461→    let sanitized: String = name
462→        .chars()
463→        .map(|c| {
464→            if c.is_ascii_alphanumeric() || c == '-' {
465→                c
466→            } else {
467→                '-'
468→            }
469→        })
470→        .take(42)
471→        .collect();
472→    sanitized.trim_end_matches('-').to_string()
473→}
