513→/// Build a test configuration with validation data if applicable
514→///
515→/// This is a common helper for bench, throughput, and load tests that:
516→/// 1. Loads the query set from args
517→/// 2. Applies query overrides if specified
518→/// 3. Adds validation data for scenario queries when validation is enabled
519→/// 4. Adds reference schema for validation against known good tables
520→///
521→/// # Returns
522→/// Tuple of (`QuerySet`, `NotStarted` builder)
523→pub(crate) async fn build_test_with_validation(
524→    args: &DatasetTestArgs,
525→    test_builder: NotStarted,
526→) -> anyhow::Result<(QuerySet, NotStarted)> {
527→    let query_set = args.load_query_set()?;
528→    let query_overrides = args
529→        .query_overrides
530→        .clone()
531→        .map(test_framework::queries::QueryOverrides::from);
532→    let queries = query_set.get_queries(query_overrides, None, None).await?;
533→
534→    let mut test_builder = test_builder
535→        .with_query_set(queries)
536→        .with_query_set_type(query_set.clone())
537→        .with_query_overrides(query_overrides);
538→
539→    // Add validation data if this is a scenario query set with validation enabled
540→    if args.validate
541→        && let Some(validation_data) =
542→            query_set.get_validation_data(args.scenario_query_file.as_deref())?
543→    {
544→        test_builder = test_builder.with_validation_data(validation_data);
545→    }
546→
547→    // Add reference schema if provided for validation against known good tables
548→    if let Some(ref_schema) = &args.reference_schema {
549→        test_builder = test_builder.with_reference_schema(Some(ref_schema.clone()));
550→    }
551→
552→    Ok((query_set, test_builder))
553→}
