555→pub(crate) async fn run_or_connect_spiced(
556→    args: &CommonArgs,
557→) -> anyhow::Result<(App, SpicedInstance, Option<String>)> {
558→    let (app, mut instance, api_key) = match args.spiced_start_mode {
559→        SpicedStartMode::Local if args.is_external_instance() => {
560→            println!(
561→                "Connecting to external spiced instance at: {}",
562→                args.spiced_path
563→            );
564→            let spicepod = Spicepod::load_exact(args.spicepod_path.clone()).await?;
565→            let app = AppBuilder::new(spicepod.name.clone())
566→                .with_spicepod(spicepod)
567→                .build();
568→            let instance = SpicedInstance::external(&args.spiced_path);
569→            (app, instance, None)
570→        }
571→        _ => {
572→            let (app, start_request) = get_app_and_start_request(args).await?;
573→            let (instance, api_key) = start_spiced_instance(args, start_request).await?;
574→            (app, instance, api_key)
575→        }
576→    };
577→
578→    // Skip wait_for_ready for Spice Cloud — readiness was already verified
579→    // by polling the SQL endpoint during deployment.
580→    if !matches!(args.spiced_start_mode, SpicedStartMode::SpiceCloud) {
581→        instance
582→            .wait_for_ready(std::time::Duration::from_secs(args.ready_wait))
583→            .await?;
584→    }
585→
586→    Ok((app, instance, api_key))
587→}
