204→pub(crate) async fn resolve_default_cname(
205→    client: &Client,
206→    base_url: &str,
207→    token: &str,
208→) -> anyhow::Result<String> {
209→    let regions_url = format!("{base_url}/v1/regions");
210→    let response = client.get(&regions_url).bearer_auth(token).send().await?;
211→    let regions: CloudRegionsResponse = response.error_for_status()?.json().await?;
212→
213→    // Find the region matching the `default` field, then return its cname
214→    if let Some(default_region) = &regions.default
215→        && !default_region.is_empty()
216→    {
217→        if let Some(region) = regions.regions.iter().find(|r| r.region == *default_region)
218→            && let Some(cname) = &region.cname
219→        {
220→            return Ok(cname.clone());
221→        }
222→        // Fall back to the default value itself if no matching region found
223→        return Ok(default_region.clone());
224→    }
225→
226→    if let Some(region) = regions
227→        .regions
228→        .iter()
229→        .find(|region| region.is_default && !region.disabled)
230→    {
231→        return Ok(region
232→            .cname
233→            .clone()
234→            .unwrap_or_else(|| region.region.clone()));
235→    }
236→
237→    if let Some(region) = regions.regions.iter().find(|region| !region.disabled) {
238→        return Ok(region
239→            .cname
240→            .clone()
241→            .unwrap_or_else(|| region.region.clone()));
242→    }
243→
244→    Err(anyhow::anyhow!(
245→        "Unable to determine a default Spice Cloud region (cname) for app creation"
246→    ))
247→}
