578→    // Skip wait_for_ready for Spice Cloud — readiness was already verified
579→    // by polling the SQL endpoint during deployment.
580→    if !matches!(args.spiced_start_mode, SpicedStartMode::SpiceCloud) {
581→        instance
582→            .wait_for_ready(std::time::Duration::from_secs(args.ready_wait))
583→            .await?;
