598→pub(crate) async fn get_app_and_start_request(
599→    args: &CommonArgs,
600→) -> anyhow::Result<(App, StartRequest)> {
601→    // When metrics are disabled, no Telemetry is created, so METER_PROVIDER_ONCE
602→    // remains unset and all metric operations are no-ops.
603→
604→    let mut spicepod = Spicepod::load_exact(args.spicepod_path.clone()).await?;
605→    let mut app_builder = AppBuilder::new(spicepod.name.clone()).with_spicepod(spicepod.clone());
606→
607→    if let Some(dependencies_root) = &args.spicepod_dependencies {
608→        for dependency in &spicepod.dependencies {
609→            let dependent_spicepod = Spicepod::load(&dependencies_root.join(dependency)).await?;
610→            app_builder = app_builder.with_spicepod_dependency(dependent_spicepod);
611→        }
612→    }
613→    // After we've loaded dependencies, remove.
614→    spicepod.dependencies = vec![];
615→    let app = app_builder.build();
616→
617→    let mut start_request = StartRequest::new(args.spiced_path_buf(), from_app(app.clone()))?;
618→
619→    if let Some(ref data_dir) = args.data_dir {
620→        start_request = start_request.with_data_dir(data_dir.clone());
621→    }
622→
623→    // If scrape_spiced_metrics is enabled, add --metrics flag to spiced
624→    if args.scrape_spiced_metrics {
625→        start_request = start_request
626→            .with_additional_args(vec!["--metrics".to_string(), "0.0.0.0:9090".to_string()]);
627→    }
628→
629→    Ok((app, start_request))
630→}
