666→/// * `scraper` - Optional metrics scraper to stop and process
667→/// * `emit_to_telemetry` - Whether to emit metrics to OpenTelemetry
668→/// * `attributes` - Optional attributes to attach to emitted metrics (e.g., test name)
669→///
670→/// # Returns
671→/// The collected `SpicedMetrics` if scraper was present, None otherwise
672→pub(crate) async fn process_spiced_metrics(
673→    scraper: Option<crate::spiced_metrics::MetricsScraper>,
674→    emit_to_telemetry: bool,
675→    attributes: &[test_framework::opentelemetry::KeyValue],
676→) -> Option<crate::spiced_metrics::SpicedMetrics> {
677→    let scraper = scraper?;
678→
679→    match scraper.stop().await {
680→        Ok(metrics) => {
681→            println!("\n{}", vec!["="; 30].join(""));
682→            println!("Spiced Runtime Metrics:");
683→            println!("{}", vec!["="; 30].join(""));
684→
685→            // Display and optionally emit key metrics
686→            // Note: Prometheus exporter appends _total to counter metrics
687→            if let Some(query_count) = metrics.get_counter_value("query_executions_total") {
688→                println!("Total Queries Executed: {query_count}");
689→
690→                if emit_to_telemetry {
691→                    crate::metrics::SPICED_QUERY_COUNT.record(query_count, attributes);
692→                }
693→            }
694→
695→            if let Some(cache_hits) = metrics.get_counter_value("results_cache_hits_total")
696→                && let Some(cache_requests) =
697→                    metrics.get_counter_value("results_cache_requests_total")
698→                && cache_requests > 0.0
699→            {
700→                let hit_rate = cache_hits / cache_requests;
701→                println!("Cache Hit Rate: {:.2}%", hit_rate * 100.0);
702→
703→                if emit_to_telemetry {
704→                    crate::metrics::SPICED_CACHE_HIT_RATE.record(hit_rate, attributes);
705→                }
706→            }
707→
708→            if let Some(active_conns) = metrics.get_gauge_max("query_active_count") {
709→                println!("Peak Active Connections: {active_conns}");
710→
711→                if emit_to_telemetry {
712→                    crate::metrics::SPICED_ACTIVE_CONNECTIONS.record(active_conns, attributes);
713→                }
714→            }
715→
716→            println!("{}", vec!["="; 30].join(""));
717→            Some(metrics)
718→        }
719→        Err(e) => {
720→            println!("Warning: Failed to collect spiced metrics: {e}");
721→            None
722→        }
723→    }
